"""tbv_ar.py — python wrapper for libtbv_ar.so (2-rank RDMA all-reduce over usb4_rdma).

Usage:
    ar = TbvAllReduce(rank)          # rank 0 = 192.168.100.1 side
    ar.all_reduce_(t)                # in-place SUM into t (contiguous cuda tensor)

The C lib moves bytes at the RDMA wire floor (~65-80us); the SUM is a GPU add
through pinned staging (cheap on UMA). Decode-sized tensors only (<= 1MB).
"""
import ctypes
import os

import torch

_LIB_PATHS = [
    os.path.join(os.path.dirname(os.path.abspath(__file__)), "libtbv_ar.so"),
    "/opt/venv/lib64/python3.12/site-packages/libtbv_ar.so",
]

BOX1_IP = "192.168.100.1"
PORT = int(os.environ.get("TBV_AR_PORT", "18515"))


class TbvAllReduce:
    def __init__(self, rank: int, peer_ip: str = BOX1_IP, port: int = PORT):
        lib = None
        for p in _LIB_PATHS:
            if os.path.exists(p):
                lib = ctypes.CDLL(p)
                break
        if lib is None:
            raise RuntimeError("libtbv_ar.so not found")
        lib.tbv_init.argtypes = [ctypes.c_int, ctypes.c_char_p, ctypes.c_int]
        lib.tbv_init_gpu.argtypes = [
            ctypes.c_int, ctypes.c_char_p, ctypes.c_int,
            ctypes.c_uint64, ctypes.c_int, ctypes.c_uint64,
            ctypes.c_uint64, ctypes.c_int, ctypes.c_uint64,
        ]
        lib.tbv_xfer.argtypes = [ctypes.c_uint32]
        lib.tbv_last_error.restype = ctypes.c_int
        lib.tbv_send_ptr.restype = ctypes.c_void_p
        lib.tbv_recv_ptr.restype = ctypes.c_void_p
        lib.tbv_max_bytes.restype = ctypes.c_uint32
        self._lib = lib
        # C entry point for hipLaunchHostFunc (stream host callback, no GIL)
        self._hostfn = ctypes.cast(lib.tbv_xfer_hostfn, ctypes.c_void_p)
        self._hip = ctypes.CDLL("libamdhip64.so")
        self._hip.hipLaunchHostFunc.argtypes = [
            ctypes.c_void_p, ctypes.c_void_p, ctypes.c_void_p,
        ]
        self._hip.hipLaunchHostFunc.restype = ctypes.c_int
        self._hip.hipMemcpyAsync.argtypes = [
            ctypes.c_void_p, ctypes.c_void_p, ctypes.c_size_t,
            ctypes.c_int, ctypes.c_void_p,
        ]
        self._hip.hipMemcpyAsync.restype = ctypes.c_int
        self._hip.hipMalloc.argtypes = [
            ctypes.POINTER(ctypes.c_void_p), ctypes.c_size_t,
        ]
        self._hip.hipMalloc.restype = ctypes.c_int
        self._hip.hipMemGetHandleForAddressRange.argtypes = [
            ctypes.c_void_p, ctypes.c_void_p, ctypes.c_size_t,
            ctypes.c_int, ctypes.c_ulonglong,
        ]
        self._hip.hipMemGetHandleForAddressRange.restype = ctypes.c_int
        self._hip.hipMemGetAddressRange.argtypes = [
            ctypes.POINTER(ctypes.c_void_p), ctypes.POINTER(ctypes.c_size_t),
            ctypes.c_void_p,
        ]
        self._hip.hipMemGetAddressRange.restype = ctypes.c_int

        lib.tbv_nslots.restype = ctypes.c_uint32

        # GPU-direct mode: data slots live in DEVICE memory, registered with
        # the RDMA driver as dma-buf MRs -- the wire lands straight in GPU
        # pages (no pinned-host staging buffers, no H2D recv copy).
        self.gpu_mode = os.environ.get("DS4_TBV_AR_GPU", "0") == "1"
        if self.gpu_mode:
            # torch's HIP runtime must be initialized before any ctypes HIP
            # call (a ctypes call as the process's first HIP use leaves
            # torch's lazy init crashing on top of it - GPF in libamdhip64).
            torch.cuda.init()
            # sizes must match the C layout contract before init
            max_bytes = 1 << 20
            nslots = 2
            # The slots are TORCH tensors (held forever) exported as dma-buf
            # fds. All data movement then uses torch ops on the current
            # stream, so the caching allocator and stream machinery see every
            # consumer -- ctypes memcpys are invisible to torch and let vLLM
            # reuse an input tensor's memory before an untracked async copy
            # ran (0% MTP acceptance / empty output corruption).
            self._gpu_send = torch.zeros(max_bytes, dtype=torch.uint8,
                                         device="cuda")
            self._gpu_recv = torch.zeros(nslots * max_bytes,
                                         dtype=torch.uint8, device="cuda")
            send_fd, send_off = self._export_dmabuf(self._gpu_send)
            recv_fd, recv_off = self._export_dmabuf(self._gpu_recv)
            if lib.tbv_init_gpu(rank, peer_ip.encode(), port,
                                self._gpu_send.data_ptr(), send_fd, send_off,
                                self._gpu_recv.data_ptr(), recv_fd,
                                recv_off) != 0:
                raise RuntimeError("tbv_init_gpu failed")
            self.max_bytes = lib.tbv_max_bytes()
            self.nslots = lib.tbv_nslots()
            assert self.max_bytes == max_bytes and self.nslots == nslots
        else:
            if lib.tbv_init(rank, peer_ip.encode(), port) != 0:
                raise RuntimeError("tbv_init failed")
            self.max_bytes = lib.tbv_max_bytes()
            self.nslots = lib.tbv_nslots()
            send_ptr = lib.tbv_send_ptr()
            recv_ptr = lib.tbv_recv_ptr()
            # Register the staging buffers with HIP as pinned so GPU<->staging
            # copies take the fast pinned path (UMA: plain memcpy bandwidth).
            cudart = torch.cuda.cudart()
            r1 = cudart.cudaHostRegister(send_ptr, self.max_bytes, 0)
            r2 = cudart.cudaHostRegister(recv_ptr, self.nslots * self.max_bytes, 0)
            assert int(r1) == 0 and int(r2) == 0, f"cudaHostRegister failed: {r1} {r2}"

            # CPU tensor views over the staging memory (uint8; reinterpret per call)
            self._send_cpu = self._wrap(send_ptr, self.max_bytes)
            self._recv_slots = [
                self._wrap(recv_ptr + i * self.max_bytes, self.max_bytes)
                for i in range(self.nslots)
            ]
        self._gpu_scratch = torch.empty(self.max_bytes, dtype=torch.uint8, device="cuda")
        # mirrors the C-side seq counter (both increment once per xfer)
        self._seq = 0
        self._check = os.environ.get("DS4_TBV_AR_CHECK", "0") == "1"
        if self._check:
            self._chk = open(f"/tmp/tbv_check_rank{rank}.log", "w")

    def _export_dmabuf(self, t: torch.Tensor):
        """Export a torch device tensor's backing BO as a dma-buf fd.

        The fd covers the WHOLE hipMalloc'd BO backing the tensor; the
        caching allocator may have placed the tensor at a nonzero offset
        inside it (always does in a busy vLLM worker). Return (fd, offset)
        so the MR registration accounts for it — registering at offset 0
        silently shifts every RDMA within the BO, corrupting neighboring
        tensors while the slots read zeros.
        """
        nbytes = t.numel() * t.element_size()
        assert t.data_ptr() % 4096 == 0, "slot tensor not page-aligned"
        base = ctypes.c_void_p()
        bo_size = ctypes.c_size_t()
        rc = self._hip.hipMemGetAddressRange(
            ctypes.byref(base), ctypes.byref(bo_size),
            ctypes.c_void_p(t.data_ptr()))
        if rc != 0:
            raise RuntimeError(f"hipMemGetAddressRange failed: {rc}")
        off = t.data_ptr() - base.value
        assert off % 4096 == 0 and off + nbytes <= bo_size.value
        fd = ctypes.c_int(-1)
        # 1 == hipMemRangeHandleTypeDmaBufFd
        rc = self._hip.hipMemGetHandleForAddressRange(
            ctypes.byref(fd), base, bo_size.value, 1, 0)
        if rc != 0 or fd.value < 0:
            raise RuntimeError(f"dmabuf export failed: rc={rc} fd={fd.value}")
        return fd.value, off

    @staticmethod
    def _wrap(ptr: int, nbytes: int) -> torch.Tensor:
        buf = (ctypes.c_uint8 * nbytes).from_address(ptr)
        return torch.frombuffer(buf, dtype=torch.uint8)

    def eligible(self, t: torch.Tensor) -> bool:
        return (
            t.is_cuda
            and t.is_contiguous()
            and t.numel() * t.element_size() <= self.max_bytes
            and not torch.cuda.is_current_stream_capturing()
        )

    def all_reduce_(self, t: torch.Tensor) -> torch.Tensor:
        """In-place SUM all-reduce of a contiguous cuda tensor."""
        nbytes = t.numel() * t.element_size()
        flat = t.view(-1)
        self._seq += 1
        scratch = self._gpu_scratch[:nbytes].view(t.dtype)
        if self.gpu_mode:
            slot = self._seq % self.nslots
            # torch-native: tensor -> GPU send slot (device copy, tracked)
            self._gpu_send[:nbytes].view(t.dtype).copy_(flat)
            torch.cuda.current_stream().synchronize()
            if self._lib.tbv_xfer(nbytes) != 0:
                raise RuntimeError("tbv_xfer failed")
            # peer's data landed straight in the GPU recv slot: add in place
            off = slot * self.max_bytes
            flat.add_(self._gpu_recv[off:off + nbytes].view(t.dtype))
            return t
        send_view = self._send_cpu[:nbytes].view(t.dtype)
        recv_view = self._recv_slots[self._seq % self.nslots][:nbytes].view(t.dtype)
        # GPU -> pinned staging (D2H, ~memcpy on UMA)
        send_view.copy_(flat, non_blocking=True)
        torch.cuda.current_stream().synchronize()
        # wire exchange at RDMA floor
        if self._lib.tbv_xfer(nbytes) != 0:
            raise RuntimeError("tbv_xfer failed")
        # peer data -> GPU scratch -> add
        scratch.copy_(recv_view, non_blocking=True)
        flat.add_(scratch)
        return t

    def all_reduce_out(self, t: torch.Tensor, out: torch.Tensor) -> torch.Tensor:
        """Out-of-place SUM all-reduce (vLLM communicator semantics).

        Host-async: the wire exchange runs as a stream host-callback
        (hipLaunchHostFunc -> tbv_xfer_hostfn, pure C), so the host thread
        never blocks and eager decode keeps its CPU-runs-ahead pipelining.
        Stream order guarantees: [D2H staging copy] -> [hostfn: RDMA xfer +
        wait for peer] -> [H2D recv copy] -> [add].
        """
        nbytes = t.numel() * t.element_size()
        flat = t.view(-1)
        if self._lib.tbv_last_error():
            raise RuntimeError("tbv_xfer failed in a previous round")
        self._seq += 1
        stream = torch.cuda.current_stream().cuda_stream
        scratch = self._gpu_scratch[:nbytes].view(t.dtype)
        if self.gpu_mode:
            slot = self._seq % self.nslots
            # Stream order: [torch copy into GPU send slot] -> [hostfn: RDMA
            # GPU-MR -> peer GPU-MR + wait] -> [add straight from the GPU
            # recv slot]. No pinned-host staging, no scratch copy, and every
            # consumer of tensor memory is a torch op the allocator can see.
            self._gpu_send[:nbytes].view(t.dtype).copy_(flat)
            rc = self._hip.hipLaunchHostFunc(
                ctypes.c_void_p(stream), self._hostfn, ctypes.c_void_p(nbytes))
            if rc != 0:
                raise RuntimeError(f"hipLaunchHostFunc failed: {rc}")
            off = slot * self.max_bytes
            recv_view = self._gpu_recv[off:off + nbytes].view(t.dtype)
            torch.add(flat, recv_view, out=out.view(-1))
            if self._check and self._seq <= 400:
                # DS4_TBV_AR_CHECK diagnostics: per-round checksums. The
                # peer contribution is out - in; compare against the peer's
                # logged input sum to see correct/zero/slot-shifted data.
                torch.cuda.synchronize()
                fin = flat.float().sum().item()
                fpeer = recv_view.float().sum().item()
                self._chk.write(f"{self._seq} {nbytes} in={fin:.3f} peer={fpeer:.3f}\n")
                self._chk.flush()
            return out
        send_view = self._send_cpu[:nbytes].view(t.dtype)
        recv_view = self._recv_slots[self._seq % self.nslots][:nbytes].view(t.dtype)
        send_view.copy_(flat, non_blocking=True)
        rc = self._hip.hipLaunchHostFunc(
            ctypes.c_void_p(stream), self._hostfn, ctypes.c_void_p(nbytes)
        )
        if rc != 0:
            raise RuntimeError(f"hipLaunchHostFunc failed: {rc}")
        scratch.copy_(recv_view, non_blocking=True)
        torch.add(flat, scratch, out=out.view(-1))
        return out
